ALTER TABLE users ADD INDEX idx_city_name (city, name);

-- 覆盖：只取索引里的列
EXPLAIN SELECT city, name FROM users WHERE city = '杭州';

-- 回表：phone 不在索引里
EXPLAIN SELECT city, name, phone FROM users WHERE city = '杭州';

ALTER TABLE orders ADD INDEX idx_user_created_amount (user_id, created_at, total_amount);

EXPLAIN SELECT id, created_at, total_amount
FROM orders
WHERE user_id = 1001
ORDER BY created_at DESC
LIMIT 20;
